import{_ as e,o as d,c as a,a5 as r}from"./chunks/framework.Bt0SrEfo.js";const u=JSON.parse('{"title":"Vite 工程化","description":"","frontmatter":{},"headers":[],"relativePath":"面试/Vite/index.md","filePath":"面试/Vite/index.md","lastUpdated":1789979447000}'),i={name:"面试/Vite/index.md"};function l(o,t,n,h,b,s){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="vite-工程化" tabindex="-1">Vite 工程化 <a class="header-anchor" href="#vite-工程化" aria-label="Permalink to &quot;Vite 工程化&quot;">​</a></h1><blockquote><p><strong>Vite 是 Vue 作者开发的新一代前端构建工具</strong>。dev 阶段利用浏览器原生 ESM 不打包（启动毫秒级），prod 阶段用 Rollup 打包（产物质量高）。</p><p>如果你明天面试涉及 Vite，按下面顺序看。</p></blockquote><h2 id="📚-文档清单" tabindex="-1">📚 文档清单 <a class="header-anchor" href="#📚-文档清单" aria-label="Permalink to &quot;📚 文档清单&quot;">​</a></h2><h3 id="🔥-必背-面试前-2-小时过一遍" tabindex="-1">🔥 必背（面试前 2 小时过一遍） <a class="header-anchor" href="#🔥-必背-面试前-2-小时过一遍" aria-label="Permalink to &quot;🔥 必背（面试前 2 小时过一遍）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>题目</th><th>文档</th></tr></thead><tbody><tr><td>Vite 是什么 / 解决了什么问题</td><td><a href="/面试/Vite/6-vite">vite.md</a></td></tr><tr><td>Vite 为什么启动这么快</td><td><a href="/面试/Vite/8-why_fast">why_fast.md</a></td></tr><tr><td>Vite 依赖预构建（esbuild）</td><td><a href="/面试/Vite/2-dependency_prebundling">dependency_prebundling.md</a></td></tr><tr><td>Vite 双构建：dev 用 esbuild / prod 用 Rollup</td><td><a href="/面试/Vite/3-dual_build">dual_build.md</a></td></tr><tr><td>Vite vs Webpack 全方位对比</td><td><a href="/面试/Vite/7-vs_webpack">vs_webpack.md</a></td></tr></tbody></table><h3 id="⭐-进阶" tabindex="-1">⭐ 进阶 <a class="header-anchor" href="#⭐-进阶" aria-label="Permalink to &quot;⭐ 进阶&quot;">​</a></h3><table tabindex="0"><thead><tr><th>题目</th><th>文档</th></tr></thead><tbody><tr><td>Vite HMR 原理</td><td><a href="/面试/Webpack/1-HMR">hmr.md</a></td></tr><tr><td>Vite 插件机制 + 怎么写插件</td><td><a href="/面试/Webpack/4-Plugin">plugin.md</a></td></tr><tr><td>Vite 常用配置 + Webpack 迁移</td><td><a href="/面试/Vite/1-config">config.md</a></td></tr></tbody></table><h2 id="🎯-面试速记" tabindex="-1">🎯 面试速记 <a class="header-anchor" href="#🎯-面试速记" aria-label="Permalink to &quot;🎯 面试速记&quot;">​</a></h2><h3 id="一句话回答-高频题" tabindex="-1">一句话回答（高频题） <a class="header-anchor" href="#一句话回答-高频题" aria-label="Permalink to &quot;一句话回答（高频题）&quot;">​</a></h3><p><strong>Q：Vite 为什么快？</strong></p><ol><li>dev 不打包（浏览器原生 ESM）</li><li>esbuild 预构建依赖（Go，10-100x babel）</li><li>按需编译（不访问的路由不编译）</li></ol><p><strong>Q：Vite 和 Webpack 区别？</strong></p><ul><li>Webpack：通用打包，dev 也打包（慢但稳定）</li><li>Vite：dev 不打包（快），prod 用 Rollup（稳）</li></ul><p><strong>Q：dev 用 esbuild，prod 为什么不用？</strong></p><ul><li>esbuild 的 prod 能力还不成熟（type stripping 不完整、tree-shaking 弱）</li><li>Rollup 生态成熟，产物质量更高</li></ul><h2 id="📖-推荐阅读顺序" tabindex="-1">📖 推荐阅读顺序 <a class="header-anchor" href="#📖-推荐阅读顺序" aria-label="Permalink to &quot;📖 推荐阅读顺序&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>看什么</th></tr></thead><tbody><tr><td>面试前 1 天</td><td>vite.md → why_fast.md → vs_webpack.md</td></tr><tr><td>项目经验</td><td>vs_webpack.md 第 7 节（迁移成本）</td></tr><tr><td>深度原理</td><td>dependency_prebundling.md + dual_build.md + hmr.md + plugin.md</td></tr><tr><td>实战</td><td>config.md（含 Webpack 迁移）</td></tr></tbody></table>',17)])])}const c=e(i,[["render",l]]);export{u as __pageData,c as default};
